Full earcut.hpp from memory:

```cpp
template <typename N> class Earcut {
public:
    std::vector<N> indices;
    std::size_t vertices = 0;

    template <typename Polygon>
    void operator()(const Polygon& points) {
        indices.clear();
        vertices = 0;

        if (points.empty()) return;

        double x, y;
        int threshold = 80;
        std::size_t len = 0;

        for (size_t i = 0; threshold >= 0 && i < points.size(); i++) {
            threshold -= static_cast<int>(points[i].size());
            len += points[i].size();
        }

        //estimate size of nodes and indices
        nodes_.reserve(len * 3 / 2);
        indices.reserve(len + points[0].size());

        Node* outerNode = linkedList(points[0], true);
        if (!outerNode || outerNode->prev == outerNode->next) return;

        if (points.size() > 1) outerNode = eliminateHoles(points, outerNode);

        // if the shape is not too simple, we'll use z-order curve hash later; calculate polygon bbox
        hashing = threshold < 0;
        if (hashing) {
            Node* p = outerNode->next;
            double minX = outerNode->x;
            double minY = outerNode->y;
            double maxX = outerNode->x;
            double maxY = outerNode->y;
            do {
                x = p->x;
                y = p->y;
                minX = std::min<double>(minX, x);
                minY = std::min<double>(minY, y);
                maxX = std::max<double>(maxX, x);
                maxY = std::max<double>(maxY, y);
                p = p->next;
            } while (p != outerNode);
            inv_size = std::max<double>(maxX - minX, maxY - minY);
            inv_size = inv_size != .0 ? (32767. / inv_size) : .0;
        }

        earcutLinked(outerNode);

        nodes_.clear();
    }

private:
    std::vector<Node> nodes_;
    double inv_size = 0;
    bool hashing = false;

    // Creates a circular doubly linked list from polygon points in the specified winding order.
    template <typename Ring>
    Node* linkedList(const Ring& points, bool clockwise) {
        double x, y;
        Node* last = nullptr;

        if (clockwise == (signedArea(points) > 0)) {
            for (const auto& p : points) last = insertNode(vertices++, p[0], p[1], last);
        } else {
            for (int64_t i = static_cast<int64_t>(points.size()) - 1; i >= 0; i--) {
                last = insertNode(vertices++, points[i][0], points[i][1], last);
            }
        }

        if (last && equals(last, last->next)) {
            removeNode(last);
            last = last->next;
        }

        return last;
    }

    Node* filterPoints(Node* start, Node* end = nullptr) {
        if (!start) return start;
        if (!end) end = start;

        Node* p = start;
        bool again;
        do {
            again = false;

            if (!p->steiner && (equals(p, p->next) || area(p->prev, p, p->next) == 0)) {
                removeNode(p);
                p = end = p->prev;

                if (p == p->next) break;
                again = true;
            } else {
                p = p->next;
            }
        } while (again || p != end);

        return end;
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    void earcutLinked(Node* ear, int pass = 0) {
        if (!ear) return;

        // interlink polygon nodes in z-order
        if (!pass && hashing) indexCurve(ear);

        Node* stop = ear;
        Node* prev;
        Node* next;

        int iterations = 0;

        // iterate through ears, slicing them one by one
        while (ear->prev != ear->next) {
            iterations++;
            prev = ear->prev;
            next = ear->next;

            if (hashing ? isEarHashed(ear) : isEar(ear)) {
                // cut off the triangle
                indices.emplace_back(prev->i);
                indices.emplace_back(ear->i);
                indices.emplace_back(next->i);

                removeNode(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = next->next;
                stop = next->next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if (ear == stop) {
                // try filtering points and slicing again
                if (!pass) earcutLinked(filterPoints(ear), 1);

                // if this didn't work, try curing all small self-intersections locally
                else if (pass == 1) {
                    ear = cureLocalIntersections(filterPoints(ear));
                    earcutLinked(ear, 2);
                }

                // as a last resort, try splitting the remaining polygon into two
                else if (pass == 2) splitEars(ear);

                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    bool isEar(Node* ear) {
        Node* a = ear->prev;
        Node* b = ear;
        Node* c = ear->next;

        if (area(a, b, c) >= 0) return false; // reflex, can't be an ear

        // now make sure we don't have other points inside the potential ear
        Node* p = ear->next->next;

        while (p != ear->prev) {
            if (pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
                area(p->prev, p, p->next) >= 0)
                return false;
            p = p->next;
        }

        return true;
    }

    bool isEarHashed(Node* ear) {
        Node* a = ear->prev;
        Node* b = ear;
        Node* c = ear->next;

        if (area(a, b, c) >= 0) return false; // reflex, can't be an ear

        // triangle bbox; min & max are calculated like this for speed
        double minTX = std::min<double>(a->x, std::min<double>(b->x, c->x));
        double minTY = std::min<double>(a->y, std::min<double>(b->y, c->y));
        double maxTX = std::max<double>(a->x, std::max<double>(b->x, c->x));
        double maxTY = std::max<double>(a->y, std::max<double>(b->y, c->y));

        // z-order range for the current triangle bbox;
        int32_t minZ = zOrder(minTX, minTY);
        int32_t maxZ = zOrder(maxTX, maxTY);

        // first look for points inside the triangle in increasing z-order
        Node* p = ear->nextZ;

        while (p && p->z <= maxZ) {
            if (p != ear->prev && p != ear->next &&
                pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
                area(p->prev, p, p->next) >= 0)
                return false;
            p = p->nextZ;
        }

        // then look for points in decreasing z-order
        p = ear->prevZ;

        while (p && p->z >= minZ) {
            if (p != ear->prev && p != ear->next &&
                pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
                area(p->prev, p, p->next) >= 0)
                return false;
            p = p->prevZ;
        }

        return true;
    }

    // go through all polygon nodes and cure small local self-intersections
    Node* cureLocalIntersections(Node* start) {
        Node* p = start;
        do {
            Node* a = p->prev;
            Node* b = p->next->next;

            // a self-intersection where edge (v1,v2) intersects (v3,v4)
            if (!equals(a, b) && intersects(a, p, p->next, b) && locallyInside(a, b) && locallyInside(b, a)) {
                indices.emplace_back(a->i);
                indices.emplace_back(p->i);
                indices.emplace_back(b->i);

                // remove two nodes involved
                removeNode(p);
                removeNode(p->next);

                p = start = b;
            }
            p = p->next;
        } while (p != start);

        return filterPoints(p);
    }

    // try splitting polygon into two and triangulate them independently
    void splitEars(Node* start) {
        // look for a valid diagonal that divides the polygon into two
        Node* a = start;
        do {
            Node* b = a->next->next;
            while (b != a->prev) {
                if (a->i != b->i && isValidDiagonal(a, b)) {
                    // split the polygon in two by the diagonal
                    Node* c = splitPolygon(a, b);

                    // filter colinear points around the cuts
                    a = filterPoints(a, a->next);
                    c = filterPoints(c, c->next);

                    // run earcut on each half
                    earcutLinked(a);
                    earcutLinked(c);
                    return;
                }
                b = b->next;
            }
            a = a->next;
        } while (a != start);
    }

    // link every hole into the outer loop, producing a single-ring polygon without holes
    Node* eliminateHoles(const Polygon& points, Node* outerNode) {
        std::vector<Node*> queue;
        for (size_t i = 1; i < points.size(); i++) {
            Node* list = linkedList(points[i], false);
            if (list) {
                if (list == list->next) list->steiner = true;
                queue.push_back(getLeftmost(list));
            }
        }
        std::sort(queue.begin(), queue.end(), [](const Node* a, const Node* b) {
            return a->x < b->x;
        });

        // process holes from left to right
        for (size_t i = 0; i < queue.size(); i++) {
            outerNode = eliminateHole(queue[i], outerNode);
        }

        return outerNode;
    }

    // find a bridge between vertices that connects hole with an outer ring and and link it
    Node* eliminateHole(Node* hole, Node* outerNode) {
        Node* bridge = findHoleBridge(hole, outerNode);
        if (!bridge) {
            return outerNode;
        }

        Node* bridgeReverse = splitPolygon(bridge, hole);

        filterPoints(bridgeReverse, bridgeReverse->next);

        return filterPoints(bridge, bridge->next);
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    Node* findHoleBridge(Node* hole, Node* outerNode) {
        Node* p = outerNode;
        double hx = hole->x;
        double hy = hole->y;
        double qx = -std::numeric_limits<double>::infinity();
        Node* m = nullptr;

        // find a segment intersected by a ray from the hole's leftmost vertex to the left;
        // segment's endpoint with lesser x will be potential connection vertex
        do {
            if (hy <= p->y && hy >= p->next->y && p->next->y != p->y) {
                double x = p->x + (hy - p->y) * (p->next->x - p->x) / (p->next->y - p->y);
                if (x <= hx && x > qx) {
                    qx = x;
                    m = p->x < p->next->x ? p : p->next;
                    if (x == hx) return m; // hole touches outer segment; pick leftmost endpoint
                }
            }
            p = p->next;
        } while (p != outerNode);

        if (!m) return 0;

        // look for points inside the triangle of hole vertex, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the vertex of the minimum angle with the ray as connection vertex
        Node* stop = m;
        double tanMin = std::numeric_limits<double>::infinity();
        double tanCur = 0;

        p = m;
        double mx = m->x;
        double my = m->y;

        do {
            if (hx >= p->x && p->x >= mx && hx != p->x &&
                pointInTriangle(hy < my ? hx : qx, hy, mx, my, hy < my ? qx : hx, hy, p->x, p->y)) {
                tanCur = std::abs(hy - p->y) / (hx - p->x); // tangential

                if (locallyInside(p, hole) &&
                    (tanCur < tanMin || (tanCur == tanMin && (p->x > m->x || area(m->prev, m, p->prev) < 0)))) {
                    m = p;
                    tanMin = tanCur;
                }
            }

            p = p->next;
        } while (p != stop);

        return m;
    }

    // whether sector in vertex m contains sector in vertex p in the same coordinates
    bool sectorContainsSector(Node* m, Node* p) {
        return area(m->prev, m, p->prev) < 0 && area(p->next, m, m->next) < 0;
    }

    // interlink polygon nodes in z-order
    void indexCurve(Node* start) {
        Node* p = start;
        do {
            p->z = zOrder(p->x, p->y);
            p->prevZ = p->prev;
            p->nextZ = p->next;
            p = p->next;
        } while (p != start);

        p->prevZ->nextZ = nullptr;
        p->prevZ = nullptr;

        sortLinked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
