        Node* p;
        Node* q;
        Node* e;
        Node* tail;
        int i, numMerges, pSize, qSize;
        int inSize = 1;

        for (;;) {
            p = list;
            list = nullptr;
            tail = nullptr;
            numMerges = 0;

